"""Adapt a copilot context into the classifier's neutral request shape."""

from rasa.builder.copilot.constants import ROLE_ASSISTANT, ROLE_USER
from rasa.builder.copilot.message_classifier.models import (
    ClassificationRequest,
    ClassificationTurn,
)
from rasa.builder.copilot.models import (
    CopilotContext,
    EventContent,
    ResponseCategory,
    UserChatMessage,
)
from rasa.builder.copilot.utils import filter_chat_history_messages


def classification_request_from_context(
    context: CopilotContext,
) -> ClassificationRequest:
    """Adapt a ``CopilotContext`` to the classifier's neutral request.

    Reproduces exactly what ``MessageClassifier`` used to extract from the
    context itself: the last user message (with its tracker-event attachments)
    as the turn to classify, and everything but the literal last history
    element — filtered to user/copilot turns, guardrails-flagged turns
    excluded — as history.

    Args:
        context: The copilot context to classify from.

    Returns:
        The neutral classification request. ``turns`` is empty when the
        context holds no user message, which the classifier fails open on.
    """
    latest_user_message = context.get_last_user_message()
    if latest_user_message is None:
        return ClassificationRequest(turns=())

    history = filter_chat_history_messages(
        context.copilot_chat_history[:-1],
        excluded_response_categories=[ResponseCategory.GUARDRAILS_POLICY_VIOLATION],
    )
    history_turns = tuple(
        ClassificationTurn(
            role=ROLE_USER if isinstance(message, UserChatMessage) else ROLE_ASSISTANT,
            content=message.get_flattened_text_content(),
        )
        for message in history
    )
    return ClassificationRequest(
        turns=(
            *history_turns,
            ClassificationTurn(
                role=ROLE_USER,
                content=latest_user_message.get_flattened_text_content(),
            ),
        ),
        attachments=tuple(latest_user_message.get_content_blocks_by_type(EventContent)),
    )
